            <div style={{ fontSize: 12.5, color: 'var(--text1)', fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{profile.name?.split(' ')[0] || 'User'}</div>
